data class Page(val data: List<Int>, val nextKey: Int?)

fun load(key: Int, size: Int): Page {
    val start = key * size
    val end = minOf(start + size, 7)
    return Page((start until end).toList(), if (end >= 7) null else key + 1)
}

fun main() {
    var key: Int? = 0
    val loaded = mutableListOf<Int>()
    while (key != null) {
        val page = load(key, 3)
        loaded += page.data
        key = page.nextKey
    }
    println("${loaded.size} items, last=${loaded.last()}")
}

@Composable
fun FeedList(viewModel: FeedViewModel) {
    val items = viewModel.feed.collectAsLazyPagingItems()
    LazyColumn {
        items(count = items.itemCount, key = items.itemKey { it.id }) { index ->
            items[index]?.let { PostRow(it) }
        }
    }
}

val themeFlow: Flow<String> = context.dataStore.data
    .catch { e ->
        if (e is IOException) emit(emptyPreferences()) else throw e
    }
    .map { prefs -> prefs[THEME_KEY] ?: "system" }

when (items.loadState.append) {
    is LoadState.Loading -> item { CircularProgressIndicator() }
    is LoadState.Error -> item {
        Button(onClick = { items.retry() }) { Text("Retry") }
    }
    is LoadState.NotLoading -> Unit
}

class FeedViewModel(repo: FeedRepository) : ViewModel() {
    val feed: StateFlow<PagingData<Post>> = repo.pager().flow
        .stateIn(viewModelScope, SharingStarted.Lazily, PagingData.empty())
}

suspend fun increment() {
    val current = dataStore.data.first()[COUNT] ?: 0
    dataStore.edit { prefs ->
        prefs[COUNT] = current + 1
    }
}
